//! Dead-code elimination must preserve the observable byte returned by boolless.

use crate::common;
#[path = "common/corpus.rs"]
mod corpus;

use corpus::{assert_c_behavior, Corpus, C_TYPES};
use kuna_decomp::dtype::type_metatype;
use kuna_num::opcodes::OpCode;

#[test]
fn boolless_deadcode_preserves_global_read_and_return() {
    let mut corpus = Corpus::load("boolless");
    // Name the input by its real storage instead of pinning an autogenerated
    // global name. The instruction bytes and script remain unchanged.
    corpus.command("map addr [INTMEM,0x52] uint1 input_byte")
        .expect("name boolless's byte input");
    let data = corpus.run_to_function("boolless");
    let fd = data.fd.as_ref().expect("script decompiled boolless");
    let proto = fd.get_func_proto();
    assert_eq!(proto.num_params(), 0);
    assert_eq!(proto.get_output().get_size(), 1, "8051 ACC is a byte return, not void");
    assert_eq!(
        proto.get_output_type().expect("recovered return type").get_metatype(),
        type_metatype::TYPE_UINT,
        "the global byte must not become a signed return"
    );

    let alive: Vec<_> = fd.obank().iter_alive().collect();
    let returns: Vec<_> = alive.iter()
        .map(|&id| fd.obank().get(id).unwrap())
        .filter(|op| op.code() == OpCode::CPUI_RETURN)
        .collect();
    assert!(!returns.is_empty(), "boolless must return to its caller");
    for op in returns {
        let value = op.get_in(1).expect("RETURN must retain its observable value");
        assert_eq!(fd.vbank().get(value).unwrap().get_size(), 1);
    }

    let body = corpus.render_c();
    assert_c_behavior(
        &common::scratch_file("boolless-byte-return", "c"),
        &format!("{C_TYPES}\nuint1 input_byte;"),
        &body,
        r#"
int main(void) {
    for (unsigned input = 0; input < 256; ++input) {
        input_byte = input;
        unsigned actual = boolless();
        unsigned expected = input < 11 ? 1 : input;
        if (actual != expected || input_byte != input) return 1;
    }
    return 0;
}
"#,
    );
}


